import{_ as o,C as r,o as n,c as i,aj as e,E as a}from"./framework.js";const u=JSON.parse('{"title":"Basic · Access Control Tab | Settings / Basic | Admin CMS","description":"Controls who can access which paths on the site: site type (public / member / private), path allow/deny lists, single sign-on, geo restrictions, request rate limits and blocks, CORS, and…","frontmatter":{"title":"Basic · Access Control Tab | Settings / Basic | Admin CMS","description":"Controls who can access which paths on the site: site type (public / member / private), path allow/deny lists, single sign-on, geo restrictions, request rate limits and blocks, CORS, and…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/basic/access.html"}]]},"headers":[],"relativePath":"cms/settings/basic/access.md","filePath":"en/cms/settings/basic/access.md","lastUpdated":1781010536000}'),c={name:"cms/settings/basic/access.md"};function d(l,t,h,g,p,b){const s=r("DocImage");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="basic-·-access-control-tab" tabindex="-1">Basic · Access Control Tab <a class="header-anchor" href="#basic-·-access-control-tab" aria-label="Permalink to &quot;Basic · Access Control Tab&quot;">​</a></h1><blockquote><p>Tab: <strong>Access Control</strong> · <code>name=access</code><br> Deep link: <code>/_Admin/system/settings?SiteId={siteGuid}&amp;name=access</code></p></blockquote><p>Controls <strong>who can access which paths</strong> on the site: site type (public / member / private), path allow/deny lists, single sign-on, geo restrictions, request rate limits and blocks, CORS, and cloud <strong>development password</strong> preview mode.</p>',3)),a(s,{src:"/cms/settings/settings-basic-access.png",alt:"Access Control tab",width:"1120"}),t[1]||(t[1]=e('<h2 id="site-type" tabindex="-1">Site Type <a class="header-anchor" href="#site-type" aria-label="Permalink to &quot;Site Type&quot;">​</a></h2><p>The <strong>Site type</strong> dropdown (<code>siteType</code>) sets the default access policy when no special path matches. Common values include <strong>Public</strong> (<code>p</code>), <strong>Member</strong> (<code>m</code>), <strong>Private</strong> (<code>o</code>), etc. (per <code>getTypes</code> API).</p><p>When the type is <strong>not public</strong>, the <strong>Path mode</strong> section appears:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Path mode</strong></td><td><strong>Include paths</strong> (only listed paths allowed) or <strong>Exclude paths</strong> (listed paths denied; others allowed)</td></tr><tr><td><strong>Path list</strong></td><td>Multiple path patterns; <strong>Add</strong> / <strong>Delete</strong> rows</td></tr><tr><td><strong>Single sign-on</strong></td><td><code>ssoLogin</code>: works with SSO integration (must be configured under <a href="./../integrations/">Integrations</a>)</td></tr></tbody></table><h2 id="visitor-country-region-restrictions" tabindex="-1">Visitor Country / Region Restrictions <a class="header-anchor" href="#visitor-country-region-restrictions" aria-label="Permalink to &quot;Visitor Country / Region Restrictions&quot;">​</a></h2><p>Shown on <strong>Kooboo online servers</strong> (<code>isOnlineServer</code>). When enabled, select blocked countries/regions and a <strong>page</strong> for blocked visitors to land on.</p><h2 id="ip-request-rate-limiting" tabindex="-1">IP Request Rate Limiting <a class="header-anchor" href="#ip-request-rate-limiting" aria-label="Permalink to &quot;IP Request Rate Limiting&quot;">​</a></h2><p>Group <strong>IP request rate limiting</strong> (<code>rateLimitSettings</code>):</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Limit all requests</strong></td><td>When on, one limit applies site-wide; when off, configure <strong>IP</strong> and <strong>User-Agent</strong> separately with <code>withinSeconds</code> / <code>permitLimit</code></td></tr><tr><td>IP / UA rules</td><td>Multi-row key-value editor; keys are IP or UA strings</td></tr></tbody></table><h2 id="request-blocking" tabindex="-1">Request Blocking <a class="header-anchor" href="#request-blocking" aria-label="Permalink to &quot;Request Blocking&quot;">​</a></h2><p>Group <strong>Request blocking</strong> (<code>accessLimitSettings</code>):</p><table tabindex="0"><thead><tr><th>List</th><th>Description</th></tr></thead><tbody><tr><td><strong>IP blocklist</strong></td><td>Matching IPs are rejected</td></tr><tr><td><strong>User-Agent blocklist</strong></td><td>UA keyword match rejects the request</td></tr></tbody></table><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p><strong>CORS</strong> toggle (<code>enableCORS</code>): browser CORS headers when cross-origin clients access site API/resources (see UI tooltip).</p><h2 id="development-password-online-public-cloud" tabindex="-1">Development Password (Online Public Cloud) <a class="header-anchor" href="#development-password-online-public-cloud" aria-label="Permalink to &quot;Development Password (Online Public Cloud)&quot;">​</a></h2><p>Shown when <strong>online server, not private deployment</strong>, and service tier allows:</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable development password</strong></td><td>Toggles site status between <code>Published</code> and <code>Development</code></td></tr><tr><td><strong>Development password</strong></td><td>Read-only password in <code>Development</code> state; visitors must enter it to preview</td></tr></tbody></table><p>This block may be hidden on private or local environments.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Basic Settings overview</a></li><li><a href="./../../operations/visitor-logs.html">Operations · Visitor logs</a> (observe traffic; not the same as rate limits on this tab)</li><li><a href="./../request-hooks.html">Request Hooks</a> (script-level interception)</li></ul>',20))])}const w=o(c,[["render",d]]);export{u as __pageData,w as default};
